Q[329] = {
	{ 5067, "Leggings of Arcana", 50, 57, nil, "In order to create the Leggings of Arcana, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid. You will also be required to pay 50 gold pieces for the crafting of the item.", { "Venom Belcher", "Bile Spewer", "Patchwork Horror", "Ramstein the Gorger" }, from = "Malyfous's Catalogue", after = "Finkle Einhorn, At Your Service!", note = "The rest of what it asks for is found in Scholomance.", get = { 12756 } },
	{ 5263, "Above and Beyond", 60, 55, nil, "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", { "Baron Rivendare" }, from = "Duke Nicholas Zverenhoff", after = "The Truth Comes Crashing Down" },
