	{ 9017, "Anthion's Parting Words", 60, 58, "H", "Return to Mokvar in Orgimmar with a set of Beaststalker's Boots, Beaststalker's Pants and Beaststalker's Mantle.", { "Nerub'enkan", "Baron Rivendare" }, from = "Anthion Harmon", after = "The Challenge", note = "The rest of what it asks for is found in Blackrock Spire.", class = 4, get = { 22061, 22017, 22016 } },
