	{ 5125, "Aurius' Reckoning", 60, 55, nil, "", nil, from = "Aurius", after = "The Medallion of Faith", to = "Aurius", inside = true, pick = { 17044, 17045 } },
	{ 5068, "Breastplate of Bloodthirst", 60, 57, nil, "In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow. You will also be required to pay 50 gold pieces for the crafting of the item.", { "Venom Belcher", "Bile Spewer", "Patchwork Horror", "Ramstein the Gorger" }, from = "Malyfous's Catalogue", after = "Finkle Einhorn, At Your Service!", note = "The rest of what it asks for is found in Scholomance.", get = { 12757 } },
	{ 5166, "Breastplate of the Chromatic Flight", 60, 57, nil, "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor': 1 Chromatic Carapace. 10 Brilliant Chromatic Scales. 10 Blood of Heroes. 10 Frayed Abomination Stitchings.", { "Venom Belcher", "Bile Spewer", "Patchwork Horror", "Ramstein the Gorger" }, from = "Catalogue of the Wayward", after = "Catalogue of the Wayward", note = "The rest of what it asks for is found in Blackrock Spire.", get = { 12895 } },
	{ 5063, "Cap of the Scarlet Savant", 60, 57, nil, "In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread. You will also be required to pay 50 gold pieces for the crafting of the item.", { "Venom Belcher", "Bile Spewer", "Patchwork Horror", "Ramstein the Gorger" }, from = "Malyfous's Catalogue", after = "Finkle Einhorn, At Your Service!", note = "The rest of what it asks for is found in Dire Maul.", get = { 12752 } },
	{ 7642, "Collection of Goods", 60, 60, "A", "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind.", { "Stratholme Supply Crate", "Supply Crate" }, from = "Grimand Elmore", after = "The Work of Grimand Elmore", note = "The rest of what it asks for is found in Razorfen Downs.", class = 2 },
	{ 8945, "Dead Man's Plea", 60, 58, nil, "Go into Stratholme and rescue Ysida Harmon from Baron Rivendare.", { "Baron Rivendare" }, from = "Anthion Harmon", get = { 22137 } },
	{ 5243, "Houses of the Holy", 60, 55, nil, "Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", { "Stratholme Supply Crate", "Supply Crate" }, from = "Leonid Barthalomew the Revered", pick = { 13216, 13217 }, get = { 3928, 6149 } },
	{ 8933, "Just Compensation", 60, 58, "A", "Bring a Lightforge Belt and a set of Lightforge Gauntlets to Deliana in Ironforge.", { "Crimson Gallant", "Crimson Guardsman", "Rockwing Screecher", "Rockwing Gargoyle" }, from = "Deliana", after = "Return to Deliana", class = 2, get = { 22086, 22090 } },
	{ 8934, "Just Compensation", 60, 58, "A", "Bring a Devout Belt and a set of Devout Gloves to Deliana in Ironforge.", { "Archivist Galford" }, from = "Deliana", after = "Return to Deliana", note = "The rest of what it asks for is found in Blackrock Spire.", class = 16, get = { 22078, 22081 } },
	{ 8940, "Just Compensation", 60, 58, "H", "Bring a Devout Belt and a set of Devout Gloves to Mokvar in Orgrimmar.", { "Archivist Galford" }, from = "Mokvar", after = "Return to Mokvar", note = "The rest of what it asks for is found in Blackrock Spire.", class = 16, get = { 22078, 22081 } },
	{ 5463, "Menethil's Gift", 60, 57, nil, "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.", nil, from = "Leonid Barthalomew the Revered", after = "The Dying, Ras Frostwhisper", to = "Menethil's Gift" },
	{ 5848, "Of Love and Family", 60, 52, nil, "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world. Return the painting to Tirion Fordring.", { "Unfinished Painting" }, from = "Artist Renfray" },
	{ 6163, "Ramstein", 60, 56, "H", "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.", { "Ramstein the Gorger" }, from = "Nathanos Blightcaller", after = "Duskwing, Oh How I Hate Thee...", pick = { 18022, 17001 } },
	{ 5213, "The Active Agent", 60, 55, nil, "Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", { "Scourge Data" }, from = "Betina Bigglezink", after = "The Flesh Does Not Lie", pick = { 13209, 19812 } },
	{ 5251, "The Archivist", 60, 55, nil, "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", { "Archivist Galford", "Scarlet Archive" }, from = "Duke Nicholas Zverenhoff" },
	{ 5212, "The Flesh Does Not Lie", 60, 55, nil, "Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", { "Mangled Cadaver", "Plague Ghoul", "Ravaged Cadaver", "Ghoul Ravener" }, from = "Betina Bigglezink" },
	{ 5214, "The Great Fras Siabi", 60, 55, nil, "Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done.", { "Fras Siabi" }, from = "Smokey LaRue", get = { 13171 } },
	{ 8968, "The Left Piece of Lord Valthalak's Amulet", 60, 58, nil, "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", { "Jarien", "Sothos" }, from = "Bodley", after = "Components of Importance" },
	{ 5282, "The Restless Souls", 60, 55, nil, "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan.", { "Ghostly Citizen", "Spectral Citizen" }, from = "Egan", get = { 13315 } },
	{ 8991, "The Right Piece of Lord Valthalak's Amulet", 60, 58, nil, "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", { "Jarien", "Sothos" }, from = "Bodley", after = "More Components of Importance" },
	{ 5262, "The Truth Comes Crashing Down", 60, 55, nil, "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.", { "Balnazzar" }, item = "Head of Balnazzar", after = "The Archivist" },
	{ 8829, "The Ultimate Deception", 60, 60, nil, "Bring a Skin of Shadow, 3 Frayed Abomination Stitchings and 1 Twilight Cultist Robe to Aurel Goldleaf at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing XI in order to complete this quest.", { "Venom Belcher", "Bile Spewer", "Patchwork Horror", "Ramstein the Gorger" }, item = "Logistics Task Briefing XI", note = "The rest of what it asks for is found in Scholomance.", get = { 21515 } },
}

