	{ 5525, "Free Knot!", 60, 57, nil, "", { "Gordok Reaver", "Gordok Warlock", "Gordok Captain", "Gordok Mage-Lord" }, from = "Knot Thimblejack", to = "Knot Thimblejack", inside = true },
