	{ 7498, "Garona: A Study on Stealth and Treachery", 60, 54, nil, "Return the book to its rightful owners.", { "A Dusty Tome" }, item = "Garona: A Study on Stealth and Treachery", to = "Lorekeeper Kildrath", class = 8, get = { 18465 } },
